// INSERT the reading into SQLite (node:sqlite, see settings.js)
const db = global.get('db');
let stmt = context.get('stmt');
if (!stmt) {
    stmt = db.prepare(`INSERT INTO telemetry
        (ts, received_ts, device_id, seq, scenario, segment, row_idx,
         p1_out, p2_out, p3_in, p4_in, f1, f2, f3, f4,
         vfd1, vfd2, vfd3, vfd4_1, vfd4_2, valve1, valve2, gt_class, quality)
        VALUES (:ts, :received_ts, :device_id, :seq, :scenario, :segment, :row_idx,
         :p1_out, :p2_out, :p3_in, :p4_in, :f1, :f2, :f3, :f4,
         :vfd1, :vfd2, :vfd3, :vfd4_1, :vfd4_2, :valve1, :valve2, :gt_class, :quality)`);
    context.set('stmt', stmt);
}
const p = msg.payload;
const cols = ['ts', 'received_ts', 'device_id', 'seq', 'scenario', 'segment', 'p1_out', 'p2_out', 'p3_in',
    'p4_in', 'f1', 'f2', 'f3', 'f4', 'vfd1', 'vfd2', 'vfd3', 'vfd4_1', 'vfd4_2', 'valve1', 'valve2',
    'gt_class', 'quality'];
const row = { row_idx: p.row ?? null };
for (const c of cols) row[c] = p[c] ?? null;
try {
    const r = stmt.run(row);
    p.id = Number(r.lastInsertRowid);
    node.status({ fill: 'green', shape: 'ring', text: `telemetry id ${p.id}` });
} catch (e) {
    node.status({ fill: 'red', shape: 'dot', text: e.message });
    node.error(e.message, msg);
    return null;
}
return msg;

// Flow processing at the edge: validate + enrich every reading
const p = msg.payload;
const cfg = global.get('wdsConfig').decision;
const [pmin, pmax] = cfg.pressure_valid_range;
const [fmin, fmax] = cfg.flow_valid_range;

const suspect = [];
for (const k of ['p1_out', 'p2_out', 'p3_in', 'p4_in']) {
    if (typeof p[k] !== 'number' || p[k] < pmin || p[k] > pmax) suspect.push(k);
}
for (const k of ['f1', 'f2', 'f3', 'f4']) {
    if (typeof p[k] !== 'number' || p[k] < fmin || p[k] > fmax) suspect.push(k);
}
p.received_ts = Date.now();
p.transit_ms = p.received_ts - p.ts;
p.quality = suspect.length ? 'SUSPECT' : 'OK';
p.suspect = suspect;

// edge rule: immediate alert for physically impossible readings (rate-limited)
let alert = null;
const last = context.get('lastAlert') || 0;
if (suspect.length && Date.now() - last > 30000) {
    context.set('lastAlert', Date.now());
    alert = { payload: { ts: Date.now(), source: 'node-red', level: 'WARNING', type: 'EDGE_RANGE_CHECK',
        message: `Out-of-range reading on ${suspect.join(', ')} (edge rule in Node-RED)`, sensor: suspect[0] } };
}
node.status({ fill: suspect.length ? 'yellow' : 'green', shape: 'dot',
    text: `#${p.seq} ${p.scenario} ${p.quality} (${p.transit_ms} ms)` });
return [msg, alert];

const s = msg.payload;
flow.set('simStatus', s);
global.set('simStatus', s);
node.status({ fill: s.online ? 'green' : 'red', shape: 'dot',
    text: s.online ? `${s.scenario} row ${s.row}/${s.end} @ ${s.rate_hz} Hz${s.paused ? ' (paused)' : ''}` : 'offline' });
return { payload: s };

// Fan a reading out to the individual widgets
const p = msg.payload;
const n = (context.get('n') || 0) + 1;
context.set('n', n);
const chartEvery = 2;               // plot every 2nd reading to keep the browser responsive
const charts = n % chartEvery === 0;
return [
    charts ? [{ topic: 'P1 out', payload: p.p1_out }, { topic: 'P2 out', payload: p.p2_out },
              { topic: 'P3 in', payload: p.p3_in }, { topic: 'P4 in', payload: p.p4_in }] : null,
    charts ? [{ topic: 'Flow 1', payload: p.f1 }, { topic: 'Flow 2', payload: p.f2 },
              { topic: 'Flow 3', payload: p.f3 }, { topic: 'Flow 4', payload: p.f4 }] : null,
    { payload: p.p1_out }, { payload: p.p2_out }, { payload: p.p3_in }, { payload: p.p4_in },
    { payload: p },
    { payload: [
        { name: 'Pump VFD 1', value: p.vfd1, color: '#1f8fb4' },
        { name: 'Pump VFD 3', value: p.vfd3, color: '#1f8fb4' },
        { name: 'Pump VFD 4-2', value: p.vfd4_2, color: '#1f8fb4' },
        { name: 'Analog valve 1', value: p.valve1, color: '#8bc34a' },
        { name: 'Analog valve 2', value: p.valve2, color: '#8bc34a' } ] }
];

const p = msg.payload;
const n = (context.get('n') || 0) + 1;
context.set('n', n);
const chart = n % 2 === 0;
return [
    { payload: p },
    { payload: p },
    chart ? [{ topic: 'Predicted state', payload: ['NORMAL','LEAK','SENSOR_FAULT','CYBER_ATTACK'].indexOf(p.state) },
             { topic: 'Ground truth', payload: p.gt_class + 0.05 }] : null,
    chart ? { topic: 'Leak index', payload: p.leak_index } : null,
];

const db = global.get('db');
let stmt = context.get('stmt');
if (!stmt) {
    stmt = db.prepare(`INSERT INTO predictions (ts, telemetry_id, telemetry_ts, model, pred_class, pred_name,
        confidence, state, severity, zone, leak_index, gt_class, latency_ms)
        VALUES (:ts, :telemetry_id, :telemetry_ts, :model, :pred_class, :pred_name, :confidence, :state,
        :severity, :zone, :leak_index, :gt_class, :latency_ms)`);
    context.set('stmt', stmt);
}
const p = msg.payload;
const row = {};
for (const c of ['ts', 'telemetry_id', 'telemetry_ts', 'model', 'pred_class', 'pred_name', 'confidence',
    'state', 'severity', 'zone', 'leak_index', 'gt_class', 'latency_ms']) row[c] = p[c] ?? null;
stmt.run(row);
const colors = { NORMAL: 'green', LEAK: 'red', SENSOR_FAULT: 'yellow', CYBER_ATTACK: 'red' };
node.status({ fill: colors[p.state] || 'grey', shape: 'dot', text: `${p.pred_name} ${(p.confidence * 100).toFixed(0)}% | state ${p.state}` });
return msg;

const db = global.get('db');
const a = msg.payload;
db.prepare(`INSERT INTO alerts (ts, source, level, type, message, severity, zone, sensor)
            VALUES (:ts, :source, :level, :type, :message, :severity, :zone, :sensor)`)
  .run({ ts: a.ts || Date.now(), source: a.source ?? null, level: a.level ?? null, type: a.type ?? null,
         message: a.message ?? null, severity: a.severity ?? null, zone: a.zone ?? null, sensor: a.sensor ?? null });

// keep the latest 15 alerts for the table
const list = flow.get('alerts') || [];
list.unshift(a);
flow.set('alerts', list.slice(0, 15));

const toast = (a.level === 'CRITICAL' || a.level === 'WARNING')
    ? { topic: `${a.level}: ${a.type}`, payload: a.message } : null;
return [{ payload: flow.get('alerts') }, toast];

const db = global.get('db');
const c = msg.payload;
db.prepare(`INSERT INTO actions (cmd_id, ts, source, action, target, value, reason)
            VALUES (:cmd_id, :ts, :source, :action, :target, :value, :reason)`)
  .run({ cmd_id: c.cmd_id ?? null, ts: c.ts || Date.now(), source: c.source ?? null, action: c.action ?? null,
         target: c.target ?? null, value: c.value === undefined || c.value === null ? null : String(c.value),
         reason: c.reason ?? null });
const log = flow.get('actionLog') || [];
log.unshift({ cmd_id: c.cmd_id, ts: c.ts, source: c.source, action: c.action, target: c.target,
              value: c.value, reason: c.reason, response_ms: null });
flow.set('actionLog', log.slice(0, 12));
return { payload: flow.get('actionLog') };

const db = global.get('db');
const a = msg.payload;
const log = flow.get('actionLog') || [];
if (a.type === 'ack' && a.action === 'process_effect') {
    // effect of the action on the (replayed) process, e.g. leak contained
    db.prepare(`INSERT INTO actions (cmd_id, ts, source, action, target, value, ack_ts, effect)
                VALUES (NULL, :ts, 'iot-node', 'process_effect', :target, :value, :ts, :effect)`)
      .run({ ts: a.ack_ts, target: a.target ?? null, value: String(a.value), effect: a.effect ?? null });
    log.unshift({ ts: a.ack_ts, source: 'iot-node', action: 'process effect', target: a.effect,
                  value: `${a.value} readings skipped`, response_ms: null });
} else if (a.type === 'ack') {
    const resp = a.cmd_ts ? a.ack_ts - a.cmd_ts : null;
    db.prepare(`UPDATE actions SET ack_ts = :ack_ts, response_ms = :resp, effect = :effect WHERE cmd_id = :cmd_id`)
      .run({ ack_ts: a.ack_ts, resp, effect: a.effect ?? null, cmd_id: a.cmd_id ?? '' });
    const entry = log.find(e => e.cmd_id && e.cmd_id === a.cmd_id);
    if (entry) { entry.response_ms = resp; entry.effect = a.effect; }
}
flow.set('actionLog', log.slice(0, 12));
return [{ payload: flow.get('actionLog') }, { payload: a.state }];

// one setting -> engine config message
const out = {};
out[msg.topic] = msg.payload;
return { payload: out };

const c = msg.payload;
flow.set('engineCfg', c);
node.status({ fill: c.auto_mode ? 'green' : 'grey', shape: 'dot', text: `${c.active_model} | auto=${c.auto_mode}` });
return [
    { payload: c.auto_mode },
    { options: c.available_models.map(m => ({ [m + (m === c.best_model ? ' (best)' : '')]: m })), payload: c.active_model },
    { payload: c.min_confidence },
    { payload: c.votes_required },
];

// add id/timestamp so the acknowledgement can be matched
const c = Object.assign({}, msg.payload);
c.cmd_id = 'ui-' + Date.now();
c.ts = Date.now();
c.source = 'dashboard';
c.reason = c.reason || 'manual override from dashboard';
return { payload: c };

const db = global.get('db');
for (const t of ['telemetry', 'predictions', 'alerts', 'actions', 'kpi_log']) db.exec(`DELETE FROM ${t}`);
db.exec('VACUUM');
flow.set('alerts', []);
node.status({ fill: 'blue', shape: 'dot', text: 'cleared ' + new Date().toLocaleTimeString() });
return { topic: 'Database', payload: 'All recorded data deleted' };

const k = msg.payload;
const n = (context.get('n') || 0) + 1;
context.set('n', n);
if (n % 5 === 0) {
    global.get('db').prepare('INSERT INTO kpi_log (ts, data) VALUES (:ts, :data)')
        .run({ ts: k.ts, data: JSON.stringify(k) });
}
const s = (o, unit) => o ? `${o.mean} ${unit} (min ${o.min}, max ${o.max}, n=${o.n})` : '—';
const pct = v => v === null || v === undefined ? '—' : (v * 100).toFixed(2) + ' %';
const rows = [
    ['ML performance (online)', ''],
    ['Readings classified', k.readings],
    ['Online accuracy', pct(k.online_accuracy)],
    ['Recall per class', Object.entries(k.online_recall || {}).map(([c, v]) => `${c} ${pct(v)}`).join(' · ')],
    ['Alarm-state share while actually normal (incl. restore hold-off)', pct(k.false_alarm_rate)],
    ['Events: true / detected / missed / false / wrong class',
        `${k.true_events} / ${k.detected_events} / ${k.missed_events} / ${k.false_events} / ${k.wrong_class_events}`],
    ['Closed-loop performance', ''],
    ['Detection delay (true onset → confirmed)', s(k.detection_delay_ms, 'ms')],
    ['Detection delay in readings', s(k.detection_delay_samples, '')],
    ['Response time (command → actuator ack)', s(k.response_time_ms, 'ms')],
    ['End-to-end latency (sensor reading → actuator ack)', s(k.end_to_end_latency_ms, 'ms')],
    ['True onset → first action', s(k.onset_to_action_ms, 'ms')],
    ['Control actions (engine) / unnecessary (corrective action while normal)', `${k.actions_total} / ${k.actions_while_normal}`],
    ['Manual overrides / valve closures', `${k.manual_actions} / ${k.valve_cycles}`],
    ['Process effects', JSON.stringify(k.process_effects)],
    ['Estimated water saved by isolation (flow-units × s)', k.water_saved],
    ['Computational performance', ''],
    ['Inference latency', s(k.inference_ms, 'ms')],
    ['Sensor → prediction pipeline latency', s(k.pipeline_latency_ms, 'ms')],
    ['Decision engine CPU / memory', `${k.engine_cpu_percent} % / ${k.engine_memory_mb} MB`],
    ['Active model / auto mode / state', `${k.active_model} / ${k.auto_mode} / ${k.state}`],
    ['Uptime', `${k.uptime_s} s`],
];
node.status({ text: `acc ${pct(k.online_accuracy)} | events ${k.detected_events}/${k.true_events}` });
return { payload: rows };

const m = msg.payload;
const rows = Object.entries(m.models).map(([name, r]) => ({
    name, family: r.family, best: name === m.best_model,
    accuracy: r.accuracy, precision: r.precision, recall: r.recall, f1: r.f1, far: r.false_alarm_rate,
    train: r.train_time_s, cpu: r.cpu_percent, mem: r.memory_mb, size: r.model_size_kb, latency: r.latency_ms,
    recall_cls: r.per_class }));
return { payload: { rows, generated: m.generated, n_train: m.n_train, n_test: m.n_test,
    thresholds: m.severity_thresholds, leaks: m.leak_events, t: Date.now() } };

const db = global.get('db');
const out = {};
for (const t of ['telemetry', 'predictions', 'alerts', 'actions', 'kpi_log']) {
    out[t] = db.prepare(`SELECT COUNT(*) AS n FROM ${t}`).get().n;
}
const last = db.prepare('SELECT AVG(received_ts - ts) AS transit FROM (SELECT * FROM telemetry ORDER BY id DESC LIMIT 100)').get();
out.avg_transit_ms = last.transit === null ? null : Math.round(last.transit);
const resp = db.prepare('SELECT AVG(response_ms) AS r FROM actions WHERE response_ms IS NOT NULL').get();
out.avg_response_ms = resp.r === null ? null : Math.round(resp.r);
return { payload: out };
